#include <iostream>
#include <string>
#include <vector>

int main() {
    std::string n;
    std::getline(std::cin, n);

    // Remove newline characters
    n.erase(std::remove(n.begin(), n.end(), '\n'), n.end());
    n.erase(std::remove(n.begin(), n.end(), '\r'), n.end());

    std::vector<char> a(n.begin(), n.end());
    int c = static_cast<int>(a.size());

    int i;
    for (i = c - 1; i >= 0; --i) {
        if (a[i] != '0') {
            break;
        }
    }
    c = i + 1;

    int sum = 0;
    for (i = 0; i < c / 2; ++i) {
        if (a[i] != a[c - 1 - i]) {
            sum = 1;
            break;
        }
    }

    if (sum)
        std::cout << "NO";
    else
        std::cout << "YES";

    return 0;
}

